#include <vector>
#include <list>
#include <iostream>

int main() {
    std::vector<double> source = {1.5, 2.5, 3.5};

    // 1. Initialize list<int> from vector<double>
    // Implicit conversion (double -> int) occurs.
    std::list<int> target(source.begin(), source.end());

    // Output: 1, 2, 3
    for (int x : target) {
        std::cout << x << " ";
    }
}
